record range.BoundedRange {
    start: Int
    finish: Int
    validate range::is-valid;
}

fn range.is-valid(value: range.BoundedRange) -> Bool {
    int::less-or-equal(value.start, value.finish)
}

fn range.width(value: range.BoundedRange) -> Int {
    doc "Return the distance from start to finish."
    subtract(value.finish, value.start)
}

test range.width/positive { range::width(range::BoundedRange(start: 2, finish: 7)) => 5 }
test range.width/equal-endpoints { range::width(range::BoundedRange(start: 3, finish: 3)) => 0 }
test range.width/reversed-rejected { range::width(range::BoundedRange(start: 8, finish: 2)) => error RECORD_VALIDATION_FAILED }

